#include <stdio.h>

int main(void) {
    int a[6] = {3, 9, 2, 7, 5, 4};
    int *p = a;
    int max = *p;
    int *pmax = a;
    for (p = a + 1; p < a + 6; p++) {
        if (*p > max) { max = *p; pmax = p; }
    }
    printf("max = %d\n", max);
    printf("max 的下标 = %td\n", pmax - a);
    return 0;
}
